INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_044_M2_S1', 'control valves', '1', 'control valves: Methods used to regulate control valves by measuring relevant conditions and applying defined control actions or constraints. In Final Control Elements, the focus is on the analysis, design, implementation, interpretation, or evaluation of control valves within Process Control and Instrumentation, particularly where the Final Control Elements module establishes its technical context.', 'SSD_COURSE_044_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M2_S2', 'valve characteristics', '2', 'valve characteristics refers to the relationship between control-valve opening and flow capacity under specified pressure conditions. In Final Control Elements, the focus is on the analysis, design, implementation, interpretation, or evaluation of valve characteristics within Process Control and Instrumentation, particularly where the Final Control Elements module establishes its technical context.', 'SSD_COURSE_044_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M2_S3', 'actuators', '3', 'actuators: Devices that convert a control signal or available energy into physical action, such as force, motion, flow, pressure, or position. In Final Control Elements, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_044_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M2_S4', 'positioners', '4', 'positioners: Devices that regulate valve position so it follows the controller or command signal. In Final Control Elements, the focus is on the analysis, design, implementation, interpretation, or evaluation of positioners within Process Control and Instrumentation, particularly where the Final Control Elements module establishes its technical context.', 'SSD_COURSE_044_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M2_S5', 'sizing principles', '5', 'sizing principles: Rules for selecting measurement and final-control equipment to meet required range, capacity, response, and process conditions. In Final Control Elements, the focus is on the analysis, design, implementation, interpretation, or evaluation of sizing principles within Process Control and Instrumentation, particularly where the Final Control Elements module establishes its technical context.', 'SSD_COURSE_044_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M3_S1', 'first-order and higher-order models', '1', 'first-order and higher-order models: Dynamic process models representing one or more energy-storage or response modes. In Process Dynamics, the focus is on the analysis, design, implementation, interpretation, or evaluation of first-order and higher-order models within Process Control and Instrumentation, particularly where the Process Dynamics module establishes its technical context.', 'SSD_COURSE_044_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M3_S2', 'dead time', '2', 'dead time refers to the delay between a process input change and the beginning of its observable output response. In Process Dynamics, the focus is on the analysis, design, implementation, interpretation, or evaluation of dead time within Process Control and Instrumentation, particularly where the Process Dynamics module establishes its technical context.', 'SSD_COURSE_044_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M3_S3', 'process gain', '3', 'process gain refers to the change in a process output relative to a change in an input variable around an operating point. In Process Dynamics, the focus is on the analysis, design, implementation, interpretation, or evaluation of process gain within Process Control and Instrumentation, particularly where the Process Dynamics module establishes its technical context.', 'SSD_COURSE_044_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M3_S4', 'dynamic testing', '4', 'dynamic testing refers to a procedure for assessing dynamic testing under specified conditions using defined measurements, criteria, and acceptance requirements. In Process Dynamics, the focus is on the analysis, design, implementation, interpretation, or evaluation of dynamic testing within Process Control and Instrumentation, particularly where the Process Dynamics module establishes its technical context.', 'SSD_COURSE_044_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M4_S1', 'closed-loop control', '1', 'closed-loop control: Methods used to regulate closed-loop control by measuring relevant conditions and applying defined control actions or constraints. In Feedback Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of closed-loop control within Process Control and Instrumentation, particularly where the Feedback Control module establishes its technical context.', 'SSD_COURSE_044_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M4_S2', 'PID structure', '2', 'PID structure refers to a feedback-control structure combining proportional, integral, and derivative actions. In Feedback Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of PID structure within Process Control and Instrumentation, particularly where the Feedback Control module establishes its technical context.', 'SSD_COURSE_044_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M4_S3', 'stability', '3', 'stability: Property describing whether a system returns toward an acceptable state or bounded response after a perturbation, according to the stability criterion appropriate to the system model. In Feedback Control, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_044_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M4_S4', 'setpoint tracking', '4', 'setpoint tracking: Controller performance in driving a process variable toward a changing desired setpoint. In Feedback Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of setpoint tracking within Process Control and Instrumentation, particularly where the Feedback Control module establishes its technical context.', 'SSD_COURSE_044_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M4_S5', 'disturbance rejection', '5', 'disturbance rejection: Controller performance in limiting the effect of external or unmeasured disturbances on a process variable. In Feedback Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of disturbance rejection within Process Control and Instrumentation, particularly where the Feedback Control module establishes its technical context.', 'SSD_COURSE_044_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M5_S1', 'Ziegler-Nichols', '1', 'Ziegler-Nichols: Empirical controller-tuning rules based on process response or sustained oscillation characteristics. In Controller Tuning, the focus is on the analysis, design, implementation, interpretation, or evaluation of Ziegler-Nichols within Process Control and Instrumentation, particularly where the Controller Tuning module establishes its technical context.', 'SSD_COURSE_044_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M5_S2', 'Cohen-Coon', '2', 'Cohen-Coon: Controller-tuning correlations designed for processes approximated by first-order dynamics with dead time. In Controller Tuning, the focus is on the analysis, design, implementation, interpretation, or evaluation of Cohen-Coon within Process Control and Instrumentation, particularly where the Controller Tuning module establishes its technical context.', 'SSD_COURSE_044_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M5_S3', 'Internal Model Control (IMC)', '3', 'IMC: Internal Model Control, a control-design approach that uses an explicit process model and a chosen robustness or filtering parameter. In Controller Tuning, the focus is on the analysis, design, implementation, interpretation, or evaluation of IMC within Process Control and Instrumentation, particularly where the Controller Tuning module establishes its technical context.', 'SSD_COURSE_044_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M5_S4', 'Control-system robustness', '4', 'Control-system robustness: Ability of a control system to maintain acceptable performance despite model uncertainty, disturbances, parameter variation, measurement noise, or implementation imperfections. In Controller Tuning, the focus is on curricular scope: Process Control and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_044_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M5_S5', 'performance criteria', '5', 'performance criteria: Measures such as error, settling time, overshoot, effort, and robustness used to assess controller performance. In Controller Tuning, the focus is on the analysis, design, implementation, interpretation, or evaluation of performance criteria within Process Control and Instrumentation, particularly where the Controller Tuning module establishes its technical context.', 'SSD_COURSE_044_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M6_S1', 'cascade', '1', 'cascade refers to a control structure in which an inner feedback loop is regulated by the output of an outer controller. In Advanced Process Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of cascade within Process Control and Instrumentation, particularly where the Advanced Process Control module establishes its technical context.', 'SSD_COURSE_044_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M6_S2', 'feedforward', '2', 'feedforward: Control action based on measured disturbances or process inputs before their effects reach the controlled variable. In Advanced Process Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of feedforward within Process Control and Instrumentation, particularly where the Advanced Process Control module establishes its technical context.', 'SSD_COURSE_044_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M6_S3', 'ratio control', '3', 'ratio control: Methods used to regulate ratio control by measuring relevant conditions and applying defined control actions or constraints. In Advanced Process Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of ratio control within Process Control and Instrumentation, particularly where the Advanced Process Control module establishes its technical context.', 'SSD_COURSE_044_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M6_S4', 'override control', '4', 'override control: Methods used to regulate override control by measuring relevant conditions and applying defined control actions or constraints. In Advanced Process Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of override control within Process Control and Instrumentation, particularly where the Advanced Process Control module establishes its technical context.', 'SSD_COURSE_044_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M6_S5', 'model predictive control', '5', 'model predictive control: Methods used to regulate model predictive control by measuring relevant conditions and applying defined control actions or constraints. In Advanced Process Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of model predictive control within Process Control and Instrumentation, particularly where the Advanced Process Control module establishes its technical context.', 'SSD_COURSE_044_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M7_S1', 'Programmable Logic Controller (PLC)', '1', 'PLC: Programmable Logic Controller used for deterministic industrial monitoring, sequencing, logic, and control. In Industrial Control Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of PLC within Process Control and Instrumentation, particularly where the Industrial Control Systems module establishes its technical context.', 'SSD_COURSE_044_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M7_S2', 'Distributed Control System (DCS)', '2', 'DCS: Distributed Control System used to supervise and control continuous or batch industrial processes through distributed controllers. In Industrial Control Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of DCS within Process Control and Instrumentation, particularly where the Industrial Control Systems module establishes its technical context.', 'SSD_COURSE_044_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M7_S3', 'Supervisory Control and Data Acquisition (SCADA)', '3', 'SCADA: Supervisory Control and Data Acquisition system used to monitor processes and control selected remote equipment. In Industrial Control Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of SCADA within Process Control and Instrumentation, particularly where the Industrial Control Systems module establishes its technical context.', 'SSD_COURSE_044_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M7_S4', 'alarm management', '4', 'alarm management: Systematic design, prioritisation, rationalisation, monitoring, and maintenance of process alarms. In Industrial Control Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of alarm management within Process Control and Instrumentation, particularly where the Industrial Control Systems module establishes its technical context.', 'SSD_COURSE_044_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M7_S5', 'cybersecurity basics', '5', 'cybersecurity basics: Fundamental controls for protecting industrial control systems, networks, devices, and data from cyber threats. In Industrial Control Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of cybersecurity basics within Process Control and Instrumentation, particularly where the Industrial Control Systems module establishes its technical context.', 'SSD_COURSE_044_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M7_S6', 'safety instrumented systems', '6', 'safety instrumented systems: Independent instrumented systems that detect hazardous process conditions and initiate defined actions to bring a process to or maintain it in a safe state. In Industrial Control Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of safety instrumented systems within Process Control and Instrumentation, particularly where the Industrial Control Systems module establishes its technical context.', 'SSD_COURSE_044_M7_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M1_S1', 'magnetic circuits', '1', 'magnetic circuits: Magnetic paths analysed using quantities such as magnetomotive force, reluctance, flux, and flux density. In Magnetic Circuits and Electromechanical Conversion, the focus is on the analysis, design, implementation, interpretation, or evaluation of magnetic circuits within Electrical Machines, particularly where the Magnetic Circuits and Electromechanical Conversion module establishes its technical context.', 'SSD_COURSE_045_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M1_S2', 'induced EMF', '2', 'induced EMF: Voltage generated in a conductor or winding by a changing magnetic flux linkage. In Magnetic Circuits and Electromechanical Conversion, the focus is on the analysis, design, implementation, interpretation, or evaluation of induced EMF within Electrical Machines, particularly where the Magnetic Circuits and Electromechanical Conversion module establishes its technical context.', 'SSD_COURSE_045_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M1_S3', 'torque production', '3', 'torque production: Electromagnetic generation of mechanical torque through interaction between magnetic fields and current-carrying conductors. In Magnetic Circuits and Electromechanical Conversion, the focus is on the analysis, design, implementation, interpretation, or evaluation of torque production within Electrical Machines, particularly where the Magnetic Circuits and Electromechanical Conversion module establishes its technical context.', 'SSD_COURSE_045_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M1_S4', 'energy conversion', '4', 'energy conversion: Conversion between electrical and mechanical energy through electromagnetic fields in electrical machines. In Magnetic Circuits and Electromechanical Conversion, the focus is on the analysis, design, implementation, interpretation, or evaluation of energy conversion within Electrical Machines, particularly where the Magnetic Circuits and Electromechanical Conversion module establishes its technical context.', 'SSD_COURSE_045_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M2_S1', 'ideal transformer', '1', 'ideal transformer refers to an ideal transformer model with perfect coupling and no winding resistance, leakage flux, or core losses. In Transformers, the focus is on the analysis, design, implementation, interpretation, or evaluation of ideal transformer within Electrical Machines, particularly where the Transformers module establishes its technical context.', 'SSD_COURSE_045_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M2_S2', 'equivalent circuit', '2', 'equivalent circuit: Simplified circuit representation that reproduces the relevant electrical behaviour of a device or system over a specified operating range. In Transformers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_045_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M2_S3', 'losses', '3', 'losses: Power converted into heat or other losses in machine windings, cores, mechanical components, or stray fields. In Transformers, the focus is on the analysis, design, implementation, interpretation, or evaluation of losses within Electrical Machines, particularly where the Transformers module establishes its technical context.', 'SSD_COURSE_045_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M2_S4', 'regulation', '4', 'regulation: Rules and compliance mechanisms used to govern regulation within the applicable disciplinary or legal framework. In Transformers, the focus is on the analysis, design, implementation, interpretation, or evaluation of regulation within Electrical Machines, particularly where the Transformers module establishes its technical context.', 'SSD_COURSE_045_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M2_S5', 'tests', '5', 'tests: Standard electrical-machine tests used to determine parameters, losses, efficiency, and operating characteristics. In Transformers, the focus is on the analysis, design, implementation, interpretation, or evaluation of tests within Electrical Machines, particularly where the Transformers module establishes its technical context.', 'SSD_COURSE_045_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M3_S1', 'construction', '1', 'construction: Physical arrangement of machine components such as windings, magnetic cores, shafts, bearings, and insulation. In DC Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of construction within Electrical Machines, particularly where the DC Machines module establishes its technical context.', 'SSD_COURSE_045_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M3_S2', 'EMF equation', '2', 'EMF equation refers to a relation between generated EMF and machine quantities such as flux, conductors, speed, and winding arrangement. In DC Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of EMF equation within Electrical Machines, particularly where the DC Machines module establishes its technical context.', 'SSD_COURSE_045_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M3_S3', 'torque', '3', 'torque: Rotational mechanical moment produced by electromagnetic or mechanical forces in an electrical machine. In DC Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of torque within Electrical Machines, particularly where the DC Machines module establishes its technical context.', 'SSD_COURSE_045_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M3_S4', 'characteristics', '4', 'characteristics: Relationships showing how machine variables such as torque, speed, current, voltage, and excitation change with operating conditions. In DC Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of characteristics within Electrical Machines, particularly where the DC Machines module establishes its technical context.', 'SSD_COURSE_045_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M3_S5', 'speed control', '5', 'speed control: Regulation of rotational speed by manipulating an appropriate input such as voltage, current, frequency, torque, or mechanical loading. In DC Machines, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_045_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M4_S1', 'rotating magnetic field', '1', 'rotating magnetic field refers to a magnetic field of approximately constant magnitude whose axis rotates in space, forming the basis of AC-machine operation. In Induction Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of rotating magnetic field within Electrical Machines, particularly where the Induction Machines module establishes its technical context.', 'SSD_COURSE_045_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M4_S2', 'equivalent circuit', '2', 'equivalent circuit: Simplified circuit representation that reproduces the relevant electrical behaviour of a device or system over a specified operating range. In Induction Machines, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_045_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M4_S3', 'torque-slip', '3', 'torque-slip refers to the relationship between electromagnetic torque and slip in an induction motor. In Induction Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of torque-slip within Electrical Machines, particularly where the Induction Machines module establishes its technical context.', 'SSD_COURSE_045_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M4_S4', 'starting', '4', 'starting refers to the process and methods used to bring an electrical machine from standstill to operating speed safely. In Induction Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of starting within Electrical Machines, particularly where the Induction Machines module establishes its technical context.', 'SSD_COURSE_045_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M4_S5', 'speed control', '5', 'speed control: Regulation of rotational speed by manipulating an appropriate input such as voltage, current, frequency, torque, or mechanical loading. In Induction Machines, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_045_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_045_M5_S1', 'Electromotive Force (EMF)', '1', 'Electromotive Force (EMF) refers to the voltage generated in a machine winding by electromagnetic induction as magnetic flux changes relative to the winding. In Synchronous Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of EMF within Electrical Machines, particularly where the Synchronous Machines module establishes its technical context.', 'SSD_COURSE_045_M5_S1', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;